  "source": "def investigate(context, acquire):
    actions = context["actions"]
    committed_max = 0
    in_tx = False
    tx_max = 0
    for action in actions:
        op = action["op"]
        if op == "begin":
            in_tx = True
            tx_max = committed_max
        elif op == "commit":
            committed_max = tx_max
            in_tx = False
        elif op == "rollback":
            in_tx = False
        elif op == "put":
            val = action["id"]
            if in_tx:
                if val > tx_max:
                    tx_max = val
            else:
                if val > committed_max:
                    committed_max = val
        elif op == "delete":
            pass
    if in_tx:
        return tx_max + 1
    else:
        return committed_max + 1",
  "scope": "Computes the next AUTOINCREMENT ID after a sequence of put/delete/begin/commit/rollback actions on a single SQLite table.",
  "change": "Simplified to track only the maximum explicit ID ever inserted in the current transactional view, since AUTOINCREMENT uses the largest ever ROWID and deletes do not affect it. Renamed 'id' to 'val' to avoid shadowing builtins."
